//======= CONFIG ====================================
#define MAX_PRESET 0          // 1 = thickest stack + 2x2 supersampling

// ---- the stack ----
#if MAX_PRESET
    #define LAYERS 8          // sheets in the stack (max sane ~12; 5 = original)
#else
    #define LAYERS 5
#endif
#define SPACING   4.0         // gap between sheets, world units
#define TAPER     1.25        // per-sheet magnification: how far the columns splay

// ---- camera ----
#define CAM_Y       0.8
#define CAM_Z       5.5
#define SWEEP_AMP   1.5       // sideways drift of the camera
#define SWEEP_SPEED 0.5
#define FORWARD     2.2       // ray forward weight: smaller = wider field of view

// ---- Gerstner waves config ----
#define GERSTNER_AMP    0.18
#define GERSTNER_FREQ   1.4
#define GERSTNER_SPEED  1.8

// ---- the circle pattern ----
#define PATTERN_ZOOM   1.3333333   // world -> pattern space
#define SECTORS        11.0        // kaleidoscope sectors (try 7, 13, 22)
#define CIRCLE_RADIUS  0.03        // the circle the whole fractal is built from
#define SCALE1         3.00        // level 1 size ...
#define SCALE1_WOBBLE  1.0
#define SCALE1_SPEED   0.37
#define SCALE2         1.50        // level 2 size ...
#define SCALE2_WOBBLE  0.0
#define SCALE2_SPEED   8.10
#define SCALE2_PHASE   1.30
#define SCALE3         0.25        // level 3 size (the circles you see)
#define SCALE3_WOBBLE  0.0
#define SCALE3_SPEED   1.60
#define SCALE3_PHASE   2.70
#define SPIN1         -0.18        // level spins, radians per second
#define SPIN2          0.16
#define SPIN3         -0.20
#define TWIST1         0.0        // petal twist ...
#define TWIST1_SPEED   0.17
#define TWIST1_PHASE   2.00
#define TWIST2         0.00
#define TWIST2_SPEED   0.23
#define TWIST2_PHASE   1.70
#define MERGE_CIRCLE   0.15        // soft-union radius of the circles themselves
#define MERGE_LEVEL2   0.50        // ... and between the level-2 copies
#define MERGE_LEVEL1   0.21        // ... and between the level-1 copies

// ---- shading ----
#define PALETTE_FREQ   0.65        // distance -> hue
#define PALETTE_BIAS  -0.12
#define PALETTE_DRIFT 0.08        // slow palette walk
#define PALETTE_RGB    vec3(0.0, 0.33, 0.67)
#define RIPPLE_AMP     1.16        // fine ripple across the halo
#define RIPPLE_BIAS    1.34
#define RIPPLE_FREQ  170.0
#define HALO_COLOR     vec3(0.85, 1.0, 0.35)   // bright ring hugging each outline
#define HALO_DECAY    14.0
#define HALO_GAIN      1.6
#define HALO_FALLOFF   0.30
#define INNER_DARK     vec3(0.04, 0.168, 0.176)  // inside a blob ...
#define INNER_LIGHT    vec3(0.962, 1.248, 1.196)
#define INNER_RING_FREQ 30.0
#define INNER_RING_POW   5.0
#define INNER_FILL     0.55
#define INNER_BODY     0.30
#define INNER_SLAB     5.00
#define INNER_EDGE0    0.22        // fade the inside out toward the centre of the scene
#define INNER_EDGE1    0.40
#define BODY_DARKEN    1.35        // darkening washed over the surface
#define BODY_FALLOFF  15.06
#define OUTER_BOOST    1.25       // gentle banding just outside the surface
#define OUTER_BOOST_AMP 1.10
#define OUTER_BOOST_FREQ 80.0
#define OUTLINE_WIDTH  0.015
#define OUTLINE_BIAS   0.002
#define OUTLINE_COLOR  vec3(2.5)
#define DEPTH_FOG      0.12        // each sheet dims with distance
#define HALO_ALPHA     0.50        // opacity of a sheet's halo
#define HALO_FADE      1.30
#define VIGNETTE_IN    0.65
#define VIGNETTE_OUT   1.20
#define VIGNETTE_AMP   2.90

// ---- quality ----
#if MAX_PRESET
    #define AA 4                    // taps per axis (1 = off, 2 = 2x2, 3 = 3x3)
#else
    #define AA 2
#endif
// ===========================================================================
// Nothing below here needs touching to change the look.

#define SECTOR_WIDTH (6.2831853 / SECTORS)     // one kaleidoscope sector, radians

mat2 rot(float angle){ float c = cos(angle), s = sin(angle); return mat2(c, -s, s, c); }
float soften(float a, float b, float k){ return clamp(0.5 + 0.5*(a - b)/k, 0.0, 1.0); }

float hash11(float p) {
    p = fract(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

// 2D Gerstner wave displacement for UV coordinates
vec2 gerstnerWave(vec2 p, vec2 dir, float steepness, float wavelength, float speed, float time) {
    float k = 6.2831853 / wavelength;
    float f = k * (dot(dir, p) - speed * time);
    float a = steepness / k;
    return dir * (a * cos(f));
}

vec2 applyGerstner(vec2 p, float time) {
    vec2 d = vec2(0.0);
    d += gerstnerWave(p, normalize(vec2(1.0, 0.5)), GERSTNER_AMP, 2.5 * GERSTNER_FREQ, GERSTNER_SPEED, time);
    d += gerstnerWave(p, normalize(vec2(-0.7, 0.9)), GERSTNER_AMP * 0.7, 1.7 * GERSTNER_FREQ, GERSTNER_SPEED * 1.3, time);
    d += gerstnerWave(p, normalize(vec2(0.3, -1.1)), GERSTNER_AMP * 0.4, 0.9 * GERSTNER_FREQ, GERSTNER_SPEED * 1.7, time);
    return p + d;
}

// the colour of one pixel, before the vignette
vec3 sceneColor(vec2 uv){
    float time = iTime;

    // Switch de caméra automatique (Chaque cycle dure 8s)
    int camMode = int(mod(time / 8.0, 3.0));

    vec3 rayOrigin;
    vec3 target = vec3(0.0);
    vec3 upVec = vec3(0.0, 1.0, 0.0);
    float dynamicForward = FORWARD;

    if(camMode == 0) {
        // Drone Flyover
        float t = time * 0.25;
        rayOrigin = vec3(sin(t) * 4.0, cos(t * 0.8) * 4.0, 10.0 + sin(t * 0.7) * 3.0);
        target = vec3(sin(t * 0.4) * 1.5, cos(t * 0.3) * 1.5, 0.0);
        float roll = sin(t * 0.5) * 0.2;
        upVec = vec3(sin(roll), cos(roll), 0.0);
    } else if(camMode == 1) {
        // Spiral Inward
        float t = time * 0.3;
        float radius = 3.0 + sin(t * 0.5) * 2.0;
        rayOrigin = vec3(cos(t) * radius, sin(t) * radius, 11.0 + cos(t * 0.4) * 4.0);
        upVec = vec3(-sin(t * 0.2), cos(t * 0.2), 0.0);
    } else {
        // Handheld Parallax
        float t = time * 0.4;
        vec2 offset = vec2(sin(t * 1.1) * 1.2 + cos(t * 2.3) * 0.4, cos(t * 0.9) * 1.2 + sin(t * 1.7) * 0.4);
        rayOrigin = vec3(offset, 9.5 + sin(t * 0.6) * 1.5);
        target = vec3(sin(t * 0.2) * 0.5, cos(t * 0.2) * 0.5, 0.0);
        float tilt = sin(t * 1.3) * 0.08;
        upVec = vec3(cos(tilt), sin(tilt), 0.0);
        dynamicForward = FORWARD + sin(t * 0.8) * 0.3;
    }

    vec3 forward  = normalize(target - rayOrigin);
    vec3 rightDir = normalize(cross(forward, upVec));
    vec3 upDir    = cross(rightDir, forward);
    vec3 rayDir   = normalize(uv.x * rightDir + uv.y * upDir + dynamicForward * forward);

    // ONE anchor for the pattern, shared by every sheet: this ray's hit on the middle
    // plane.  This is what makes a circle the same circle on all of them.
    float refPlaneDist = (0.0 - rayOrigin.z) / rayDir.z;
    vec2  refPos = (rayOrigin + rayDir * refPlaneDist).xy * PATTERN_ZOOM;

    vec3 finalColor = vec3(0.0);

    for(int i = 0; i < LAYERS; i++) {
        float layer = float(i);
        float planeZ = (layer - 0.5 * float(LAYERS - 1)) * SPACING;
        float planeDist = (planeZ - rayOrigin.z) / rayDir.z;

        if(planeDist > 0.0) {
            vec3 hitPoint = rayOrigin + rayDir * planeDist;
            vec2 worldPos = hitPoint.xy;                    // drives the inside texture
            vec2 patternPos = refPos * (1.0 + TAPER * layer); // shared pattern + the splay

            // Apply Gerstner wave displacement to the pattern space
            patternPos = applyGerstner(patternPos, time + layer * 0.25);

            float scale1 = SCALE1 + SCALE1_WOBBLE * sin(time * SCALE1_SPEED);
            float scale2 = SCALE2 + SCALE2_WOBBLE * sin(time * SCALE2_SPEED + SCALE2_PHASE);
            float scale3 = SCALE3 + SCALE3_WOBBLE * sin(time * SCALE3_SPEED + SCALE3_PHASE);

            float spin1 = SPIN1 * time;
            float spin2 = SPIN2 * time;
            float spin3 = SPIN3 * time;
            float twist1 = TWIST1 * sin(time * TWIST1_SPEED + TWIST1_PHASE);
            float twist2 = TWIST2 * sin(time * TWIST2_SPEED + TWIST2_PHASE);

            float dist = 1e9;

            // ---- level 1 ----
            vec2  domain1 = rot(spin1) * patternPos;
            float sector1 = floor(atan(-domain1.y, domain1.x) / SECTOR_WIDTH + 0.5);

            for(int a = -1; a <= 1; a++) {
                float id1 = sector1 + float(a);
                vec4  angles1 = id1 * SECTOR_WIDTH - vec4(0.0, SECTORS, 3.0 * SECTORS, 0.0);
                mat2  idMatrix1 = mat2(cos(angles1.x), cos(angles1.y), cos(angles1.z), cos(angles1.w));
                vec2  polarPos1 = domain1 * idMatrix1 - vec2(scale1, 0.0);

                float twistAngle1 = (id1 - SECTORS * floor(id1 / SECTORS + 0.5)) * twist1;
                polarPos1 = rot(twistAngle1) * polarPos1;

                float distLevel2 = 1e9;

                // ---- level 2 ----
                vec2  domain2 = rot(spin2) * polarPos1;
                float sector2 = floor(atan(-domain2.y, domain2.x) / SECTOR_WIDTH + 0.5);

                for(int b = -1; b <= 1; b++) {
                    float id2 = sector2 + float(b);
                    vec4  angles2 = id2 * SECTOR_WIDTH - vec4(0.0, SECTORS, 3.0 * SECTORS, 0.0);
                    mat2  idMatrix2 = mat2(cos(angles2.x), cos(angles2.y), cos(angles2.z), cos(angles2.w));
                    vec2  polarPos2 = domain2 * idMatrix2 - vec2(scale2, 0.0);

                    float twistAngle2 = (id2 - SECTORS * floor(id2 / SECTORS + 0.5)) * twist2;
                    polarPos2 = rot(twistAngle2) * polarPos2;

                    float distLevel3 = 1e9;

                    // ---- level 3: the circles ----
                    vec2  domain3 = rot(spin3) * polarPos2;
                    float sector3 = floor(atan(-domain3.y, domain3.x) / SECTOR_WIDTH + 0.5);

                    for(int c = -1; c <= 1; c++) {
                        float id3 = sector3 + float(c);
                        vec4  angles3 = id3 * SECTOR_WIDTH - vec4(0.0, SECTORS, 3.0 * SECTORS, 0.0);
                        mat2  idMatrix3 = mat2(cos(angles3.x), cos(angles3.y), cos(angles3.z), cos(angles3.w));
                        vec2  polarPos3 = domain3 * idMatrix3 - vec2(scale3, 0.0);

                        float circleDist = length(polarPos3) - CIRCLE_RADIUS;

                        float blend = soften(circleDist, distLevel3, MERGE_CIRCLE);
                        distLevel3 = mix(circleDist, distLevel3, blend) - MERGE_CIRCLE * blend * (1.0 - blend);
                    }

                    float blend2 = soften(distLevel3, distLevel2, MERGE_LEVEL2);
                    distLevel2 = mix(distLevel3, distLevel2, blend2) - MERGE_LEVEL2 * blend2 * (1.0 - blend2);
                }

                float blend1 = soften(distLevel2, dist, MERGE_LEVEL1);
                dist = mix(distLevel2, dist, blend1) - MERGE_LEVEL1 * blend1 * (1.0 - blend1);
            }

            // ---- shading this sheet ----
            float blinkSpeed = 12.0;
            float blinkId = floor(time * blinkSpeed);
            float randomColorOffset = hash11(blinkId + layer * 17.13);

            float positiveDist = max(0.0, dist);
            float paletteShift = positiveDist * PALETTE_FREQ + PALETTE_BIAS + PALETTE_DRIFT * time + randomColorOffset;
            vec3  paletteColor = 0.5 + 0.5 * cos(6.2831853 * (paletteShift + PALETTE_RGB));

            float ripple = RIPPLE_BIAS + RIPPLE_AMP * cos(RIPPLE_FREQ * positiveDist);
            vec3  outerColor = paletteColor * ripple;
            outerColor += HALO_COLOR * exp(-HALO_DECAY * positiveDist) * HALO_GAIN;
            outerColor *= exp(-HALO_FALLOFF * positiveDist);

            float spotLight = pow(0.5 + 0.5 * sin(INNER_RING_FREQ * length(worldPos)), INNER_RING_POW);
            vec3  innerColor = mix(INNER_DARK, INNER_LIGHT, spotLight);
            innerColor *= INNER_FILL + INNER_BODY * (1.0 - exp(INNER_SLAB * dist));
            innerColor *= smoothstep(INNER_EDGE0, INNER_EDGE1, length(worldPos));

            vec3 color = dist > 0.0 ? outerColor : innerColor;
            color *= 1.0 - BODY_DARKEN / exp(BODY_FALLOFF * abs(dist));

            if(dist > 0.0) {
                color *= OUTER_BOOST + OUTER_BOOST_AMP * cos(OUTER_BOOST_FREQ * dist);
            }

            float outline = 1.0 - smoothstep(0.0, OUTLINE_WIDTH, abs(dist) - OUTLINE_BIAS);
            color = mix(color, OUTLINE_COLOR, outline);

            // the far sheet is the opaque backdrop; the nearer ones lay their colour over
            float coverage = dist <= 0.0 ? 1.0 : (i == 0 ? 1.0 : exp(-HALO_FADE * positiveDist) * HALO_ALPHA);
            color *= exp(-DEPTH_FOG * planeDist);

            finalColor = mix(finalColor, color, coverage);
        }
    }

    return finalColor;
}

void mainImage(out vec4 outColor, vec2 fragCoord) {
    vec2 resolution = iResolution.xy;
    vec2 uv = (fragCoord - 0.5 * resolution) / resolution.y;

    vec3 color = vec3(0.0);
    for(int y = 0; y < AA; y++)
    for(int x = 0; x < AA; x++) {
        vec2 offset = (vec2(float(x), float(y)) + 0.5) / float(AA) - 0.5;
        color += sceneColor((fragCoord + offset - 0.5 * resolution) / resolution.y);
    }
    color /= float(AA * AA);

    float vignette = pow(smoothstep(VIGNETTE_IN, VIGNETTE_OUT, length(uv)), 2.0) * VIGNETTE_AMP;
    color = mix(color, vec3(0.0), clamp(vignette, 0.0, 1.0));

    outColor = vec4(color, 1.0);
}
